INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(18501, 'Jeremiah 27:18', 'Jeremiah', 27, 18, '&nbsp;کۀ چرې هغوئ په رښتيا سره پېغمبران وى او د مالِک خُدائ د خوا نه ورته کلام ورکړے شوے وى نو بيا دې هغوئ ما ته چې مالِک خُدائ ربُ الافواج يم سوال او مِنت وکړى چې زۀ هغه پاتې شوى مقدس څيزونه بابل ته پرې نۀ ږدم چې هغوئ يوسى. او چې هغه په يروشلم کښې د مالِک خُدائ په کور او د يهوداه بادشاه په محل کښې پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18502, 'Jeremiah 27:19', 'Jeremiah', 27, 19, '&nbsp;نو مالِک خُدائ، ربُ الافواج د هغه څيزونو په حقله وفرمائيل کوم چې په يروشلم کښې پاتې وُو لکه د زېړو ستنې او د زېړو ډيګۍ، او د اوبو راوړلو ګاډۍ او نور سامانونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18503, 'Jeremiah 27:20', 'Jeremiah', 27, 20, '&nbsp;دا هم هغه پاتې شوى څيزونه دى کله چې نبوکدنضر بادشاه د يهوداه بادشاه، د يهويقيم زوئ يهوياکين او د يهوداه او يروشلم مشران سپين روبى ټول بابل ته بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18504, 'Jeremiah 27:21', 'Jeremiah', 27, 21, '&nbsp;مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى هغه څيزونو په حقله کوم چې د مالِک خُدائ په کور کښې پاتې دى او د يهوداه او په يروشلم او د بادشاه په محل کښې پاتې دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18505, 'Jeremiah 27:22', 'Jeremiah', 27, 22, '&nbsp;دا سامانونه به بابل ته يوړے شى او دا به زما د راتلو د ورځې پورې هلته وى، مالِک خُدائ داسې فرمائى چې، نو بيا به زۀ دا ټول سامان واپس راوړم او په دې ځائ کښې به يې ولګوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18506, 'Jeremiah 28:1', 'Jeremiah', 28, 1, '&nbsp;د يهوداه د بادشاه د صدقياه د بادشاهۍ په تازه ورځو کښې په هم هغه کال په پينځمه مياشت په څلورم کال د جبعون د ښار يو پېغمبر د عزور زوئ حننياه د مالِک خُدائ په کور کښې د اِمامانو او د خلقو په وړاندې ما ته خبرې وکړې او راته يې وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18507, 'Jeremiah 28:2', 'Jeremiah', 28, 2, '&nbsp;مالِک خُدائ ربُ الافواج، د بنى اِسرائيلو خُدائ پاک فرمائى چې، ”زۀ به د بابل د بادشاه جغ مات کړم چې بوج يې په خلقو باندې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18508, 'Jeremiah 28:3', 'Jeremiah', 28, 3, '&nbsp;زۀ به په دوو کالو کښې دننه دننه د مالِک خُدائ د کور هغه ټول مقدس څيزونه واپس دې ځائ ته راوړم کوم چې نبوکدنضر بادشاه بابل ته وړلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18509, 'Jeremiah 28:4', 'Jeremiah', 28, 4, '&nbsp;زۀ به هم د يهوداه بادشاه د يهويقيم زوئ يهوياکين سره د يهوداه د هغه ټولو خلقو واپس دې ځائ ته راولم کوم چې په بابل کښې جلاوطن دى. بې‌شکه چې زۀ به د بابل د بادشاه جغ مات کړم. مالِک خُدائ دا فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18510, 'Jeremiah 28:5', 'Jeremiah', 28, 5, '&nbsp;بيا يرمياه پېغمبر د اِمامانو او د هغه ټولو خلقو په مخکښې کوم چې د مالِک خُدائ په کور کښې ولاړ وُو حننياه نبى ته داسې جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18511, 'Jeremiah 28:6', 'Jeremiah', 28, 6, '&nbsp;هغۀ وفرمائيل چې، ”آمين. مالِک خُدائ دې هم داسې وکړى. هغه دې ستا پېشګوئې پوره او رښتيا کړى چې هغه به دوباره ټول د مالِک خُدائ د کور سامان سره د هغه کسانو چې بابل ته قېديان بوتلے شوى دى دلته واپس راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18512, 'Jeremiah 28:7', 'Jeremiah', 28, 7, '&nbsp;خو اوس تۀ هم هغه خبرو ته کومې چې زۀ تا ته د ټولو خلقو په وړاندې کوم غوږ ونيسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18513, 'Jeremiah 28:8', 'Jeremiah', 28, 8, '&nbsp;زما او ستا نه ډېر وړاندې پخوانو نبيانو دا پېشګوئې کړې ده چې په ډېرو مُلکونو او لويو بادشاهتونو به جنګ، قحط او وبا راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18514, 'Jeremiah 28:9', 'Jeremiah', 28, 9, '&nbsp;خو کوم يو پېغمبر چې د خير او سلامتۍ پېشګوئې کوى نو هغه به په رښتيا سره په دې وپېژندلے شى چې د مالِک خُدائ له طرفه رالېږلے شوے دے کله چې د هغۀ پېشګوئې رښتيا شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18515, 'Jeremiah 28:10', 'Jeremiah', 28, 10, '&nbsp;نو بيا حننياه د يرمياه نبى د غاړې نه جغ لرې کړو او ټوټه ټوټه يې کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18516, 'Jeremiah 28:11', 'Jeremiah', 28, 11, '&nbsp;او حننياه ټولو خلقو ته وفرمائيل چې، ”مالِک خُدائ فرمائى، زۀ به په دوو کالونو کښې دننه هم دغه شان د نبوکدنضر بادشاه جغ چې کوم هغۀ د ټولو قومونو په غاړه کښې اچولے دے لرې کړم.“ په دې خبره يرمياه د هغه ځائ نه لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18517, 'Jeremiah 28:12', 'Jeremiah', 28, 12, '&nbsp;نو بيا څۀ موده وروستو کله چې حننياه پېغمبر د يرمياه پېغمبر د څټ نه جغ مات کړو، نو بيا د مالِک خُدائ کلام په يرمياه پېغمبر نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18518, 'Jeremiah 28:13', 'Jeremiah', 28, 13, '&nbsp;”لاړ شه او حننياه ته ووايه چې، مالِک خُدائ فرمائى، تا خو د لرګى جغ مات کړو، خو د دې په ځائ به مالِک خُدائ د خلقو په غاړه کښې د اوسپنې جغ واچوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18519, 'Jeremiah 28:14', 'Jeremiah', 28, 14, '&nbsp;مالِک خُدائ، ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، زۀ به د دې ټولو قومونو په غاړه کښې د اوسپنې جغ واچوم ترڅو چې هغوئ د بابل د بادشاه نبوکدنضر خِدمت وکړى. مالِک خُدائ فرمائيلى دى، تر دې چې زۀ به د ځنګل په ځناورو باندې هم نبوکدنضر ته اختيار ورکړم چې د هغۀ خِدمت وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18520, 'Jeremiah 28:15', 'Jeremiah', 28, 15, '&nbsp;بيا يرمياه نبى حننياه نبى ته وفرمائيل چې، ”حننياه ما ته غوږ شه. مالِک خُدائ تۀ نۀ يې رالېږلے، تۀ دې قوم ته د دروغو نبوت کوې او هغوئ ستاسو په دروغو باندې باور کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18521, 'Jeremiah 28:16', 'Jeremiah', 28, 16, '&nbsp;نو ځکه بيا مالِک خُدائ په خپله فرمائى چې، زۀ اوس تا د زمکې د مخ نه اخوا کوم. په هم دې کال کښې به تۀ مړ شې، ځکه چې تا د مالِک خُدائ خلاف د سرکشۍ تعليم ورکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18522, 'Jeremiah 28:17', 'Jeremiah', 28, 17, '&nbsp;نو د هم هغه کال په اوومه مياشت حننياه پېغمبر مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18523, 'Jeremiah 29:1', 'Jeremiah', 29, 1, '&nbsp;دا د هغه خط متن دے کوم چې يرمياه پېغمبر د يروشلم نه بابل ته هغه مشرانو او اِمامانو، پېغمبرانو، او نورو ټولو خلقو ته څوک چې نبوکدنضر بادشاه د يروشلم نه بابل ته جلاوطن کړى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18524, 'Jeremiah 29:2', 'Jeremiah', 29, 2, '&nbsp;هغۀ دا د هغه وخت نه وروستو وليکلو کله چې يهوياکين بادشاه، د هغۀ مور مَلِکه، د دربار خصيان آفسران، د يهوداه او يروشلم مشران، ماهِر کسان او کاريګران د يروشليم نه شړلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18525, 'Jeremiah 29:3', 'Jeremiah', 29, 3, '&nbsp;هغۀ هغه خط د اِلعاسه د سافن زوئ او ګمرياه د خِلقياه زوئ په لاس ولېږلو، کوم چې د يهوداه بادشاه صدقياه د بابل نبوکدنضر له ولېږلو. په هغې کښې دا ليکلے شوى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18526, 'Jeremiah 29:4', 'Jeremiah', 29, 4, '&nbsp;”مالِک خُدائ ربُ الافواج، د بنى اِسرائيلو خُدائ پاک هغه ټولو خلقو ته فرمائى کوم چې ما مالِک خُدائ هغوئ د يروشلم نه بابل ته قېديان بوتلل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18527, 'Jeremiah 29:5', 'Jeremiah', 29, 5, '&nbsp;خپل ځان له په بابل کښې کورونه جوړ کړئ او په هغې کښې اوسېږئ. باغونه وکَرئ او د هغې نه خوراک کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18528, 'Jeremiah 29:6', 'Jeremiah', 29, 6, '&nbsp;تاسو ودونه وکړئ چې زامن او لوڼه مو پېدا شى. نو دغه شان بيا خپل زامن او لوڼه هم وادۀ کړئ چې د هغوئ هم بچى پېدا شى. تاسو په شمېر کښې زيات شئ نه چې کم شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18529, 'Jeremiah 29:7', 'Jeremiah', 29, 7, '&nbsp;کوم ښار ته چې ما تاسو جلاوطن کړى يئ د دغه ښار خير غواړئ. او مالِک خُدائ ته د هغې دپاره دُعا کوئ، ځکه کۀ چرې په هغې کښې خير وى، نو تاسو به هم په خير يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18530, 'Jeremiah 29:8', 'Jeremiah', 29, 8, '&nbsp;مالِک خُدائ، ربُ الافواج د بنى اِسرائيلو خُدائ پاک تاسو ته فرمائى چې، خبردار، ستاسو په مينځ کښې چې کوم نبيان او فالبين اوسيږى چې هغوئ تاسو دوکه نۀ کړى. د هغوئ خوبونو ته توجو مۀ ورکوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18531, 'Jeremiah 29:9', 'Jeremiah', 29, 9, '&nbsp;ځکه هغوئ تاسو ته زما په نوم د دروغو پېشګوئې کوى. هغوئ ما تاسو ته نۀ دى درلېږلى. مالِک خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18532, 'Jeremiah 29:10', 'Jeremiah', 29, 10, '&nbsp;مالِک خُدائ فرمائى چې، کله چې په بابل کښې ستاسو اويا کاله تېر شى، نو زۀ به ستاسو خوا ته راشم او خپله هغه د رحم وعده به پوره کړم چې تاسو بيا واپس خپل مُلک ته راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18533, 'Jeremiah 29:11', 'Jeremiah', 29, 11, '&nbsp;مالِک خُدائ فرمائى چې، ما ته د هغه منصوبو پته ده زۀ چې کومې ستاسو دپاره لرم، هغه منصوبه چې تاسو آبادوى او خوشحالوى، نه چې تاسو ته نقصان رسوى، هغه منصوبه چې تاسو ته مستقبل او اُميد درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18534, 'Jeremiah 29:12', 'Jeremiah', 29, 12, '&nbsp;بيا به په هغه وخت تاسو ما ته مِنت زارى وکړئ، ما ته به رجوع وکړئ او ما نه به دُعا وغواړئ، او زۀ به ستاسو دُعا واورم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18535, 'Jeremiah 29:13', 'Jeremiah', 29, 13, '&nbsp;تاسو به زما لټون کوئ او کۀ چرې په پوره زړۀ سره زما لټون وکړئ نو تاسو به مې پېدا کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18536, 'Jeremiah 29:14', 'Jeremiah', 29, 14, '&nbsp;مالِک خُدائ فرمائى چې، زۀ به تاسو ته اجازت درکړم چې ما پېدا کړئ. زۀ به ستاسو مُلک دوباره تاسو له درکړم. د هغه ټولو مُلکونو او ځايونو نه به تاسو واپس راولم په کومو کښې چې ما خوارۀ کړى وئ، او زۀ به تاسو هغه مُلک ته واپس راولم د کوم نه چې ما تاسو جلاوطن کړى وئ، مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18537, 'Jeremiah 29:15', 'Jeremiah', 29, 15, '&nbsp;تاسو ووايئ چې، مونږ دپاره مالِک خُدائ په بابل کښې هم پېغمبران راپېدا کړى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18538, 'Jeremiah 29:16', 'Jeremiah', 29, 16, '&nbsp;خو مالِک خُدائ ته غوږ ونيسئ چې هغه د هغه بادشاه په حقله فرمائى څوک چې د داؤد په تخت ناست دے او د هغه خلقو په حقله څوک چې په دې ښار کښې پاتې شوى دى، او ستاسو د مُلک خلقو په حقله څوک چې تاسو سره جلاوطن شوى نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18539, 'Jeremiah 29:17', 'Jeremiah', 29, 17, '&nbsp;مالِک خُدائ ربُ الافواج فرمائى چې، زۀ به په هغوئ باندې جنګ، قحط او وبا راولم او هغوئ به د هغه خرابو اينځرو په شان کړم چې د خوړلو قابل نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18540, 'Jeremiah 29:18', 'Jeremiah', 29, 18, '&nbsp;زۀ به په هغوئ جنګ، قحط او وبا نازله کړم او د هغوئ پسې به يم، او د دُنيا ټول نور قومونه چې هغوئ ته ګورى نو ورته به د يرې او دهشت مثال وى او چې چرته هم هغوئ خوارۀ کړم نو ټولو خلقو ته به يې د نفرت او سپکاوى باعث وګرځوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18541, 'Jeremiah 29:19', 'Jeremiah', 29, 19, '&nbsp;مالِک خُدائ فرمائى چې، ځکه چې هغوئ زما کلام ته غوږ نۀ نيولو، هغه پېغام چې ما بار بار د خپلو خادِمانو نبيانو په ذريعه هغوئ ته ورکړے وو. او تاسو جلاوطنو هم زما پېغام ته غوږ ونۀ نيولو، مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18542, 'Jeremiah 29:20', 'Jeremiah', 29, 20, '&nbsp;نو اوس تاسو ټولو اے جلاوطن شوو څوک چې ما د يروشلم نه بابل ته لېږلئ د مالِک خُدائ کلام واورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18543, 'Jeremiah 29:21', 'Jeremiah', 29, 21, '&nbsp;مالِک خُدائ ربُ الافواج، د بنى اِسرائيلو خُدائ پاک د اخى‌اب د قولاياه د زوئ او د صدقياه د معسياه د زوئ په حقله فرمائى چې، هغوئ تاسو ته زما په نوم د دروغو پېشګويانې وکړى، زۀ به هغوئ نبوکدنضر د بابل بادشاه ته حواله کړم، او هغه به هغوئ ستا د سترګو د وړاندې مړۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18544, 'Jeremiah 29:22', 'Jeremiah', 29, 22, '&nbsp;ځکه چې د هغوئ په وجه به، د يهوداه نه ټول جلاوطن شوى خلق څوک چې په بابل کښې قېديان دى هغوئ به داسې ښېرې کوى، مالِک خُدائ دې تاسو سره د صدقياه او اخى‌اب په شان کار وکړى څوک چې د بابل بادشاه په اور کښې سوزولى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18545, 'Jeremiah 29:23', 'Jeremiah', 29, 23, '&nbsp;ځکه چې هغوئ په بنى اِسرائيلو کښې شرمناک ګناهونه کړى دى، هغوئ د خپلو ګاونډيانو د ښځو سره د زنا باوجود، زما په نامه د دروغو پېغام خلقو ته وړاندې کړے دے د کوم چې ما هغوئ ته حُکم نۀ دے ورکړے. خو ما ته د هغوئ په حقله عِلم دے او په هغوئ باندې زۀ ګواه يم. مالِک خُدائ داسې فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18546, 'Jeremiah 29:24', 'Jeremiah', 29, 24, '&nbsp;مالِک خُدائ په بابل کښې دا پېغام سمعياه نحلامى ته راولېږلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18547, 'Jeremiah 29:25', 'Jeremiah', 29, 25, '&nbsp;”مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، تا په خپل اختيار سره يو خط صفنياه د معسياه زوئ، اِمام ته، او تا د دې نقل نورو اِمامانو او د يروشلم خلقو ته ولېږلو، چې په کښې تا وليکلو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18548, 'Jeremiah 29:26', 'Jeremiah', 29, 26, '&nbsp;تۀ مالِک خُدائ د يهويدع په ځائ اِمام جوړ کړې او هغۀ تۀ د خپل کور مشر جوړ کړې. نو تا ته په کار دى چې هر يو ليونے کس چې په دروغو سره نبوت کوى د لرګى په کنده کښې بند کړې او په غاړه کښې ورته د اوسپنې زنځير واچوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18549, 'Jeremiah 29:27', 'Jeremiah', 29, 27, '&nbsp;نو بيا تاسو د عنتوت يرمياه ته زورنه ولې نۀ ده ورکړې، چا چې ستاسو په مينځ کښې د پېغمبرۍ دعوىٰ کوله او خلقو ته يې د پېغمبرۍ خبرې کولې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18550, 'Jeremiah 29:28', 'Jeremiah', 29, 28, '&nbsp;ځکه چې مونږ ته په بابل کښې هغۀ پېغام راولېږلو، او پېشګوئې يې وکړه چې زمونږ په جلاوطنۍ کښې به ډېر وخت لګيږى. نو هغۀ ووئيل، تاسو په دې وجه کورونه جوړ کړئ او هلته په کښې اوسېږئ، باغونه وکَرئ او د هغې مېوې خورئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18551, 'Jeremiah 29:29', 'Jeremiah', 29, 29, '&nbsp;صفنياه اِمام دا خط يرمياه نبى ته ولوستلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18552, 'Jeremiah 29:30', 'Jeremiah', 29, 30, '&nbsp;او بيا د مالِک خُدائ کلام په يرمياه نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18553, 'Jeremiah 29:31', 'Jeremiah', 29, 31, '&nbsp;”ټولو جلاوطنو ته خط ورولېږه او ورته وليکه چې، مالِک خُدائ د سمعياه نحلامى په حقله فرمائى چې، هغۀ د خپل ځان نه تاسو ته پېشګوئې کړې ده، او کۀ څۀ هم چې هغه ما تاسو ته نۀ دے درلېږلے. او هغۀ تاسو داسې تيار کړئ چې د هغۀ په دروغو باندې باور وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18554, 'Jeremiah 29:32', 'Jeremiah', 29, 32, '&nbsp;نو بيا په دې وجه مالِک خُدائ داسې فرمائى چې، زۀ به سمعياه نحلامى او د دۀ اولاد ته په يقين سره سزا ورکړم. د هغۀ د خاندان نه به څوک هم ژوندى پاتې نۀ شى، او نۀ به هغوئ هغه احسانونه او نعمتونه وګورى کوم چې زۀ د خپل غوره شوى قوم سره کوم، ځکه چې هغۀ زما خلاف خلقو ته د سرکشۍ کولو لمسون وکړو، مالِک خُدائ فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18555, 'Jeremiah 30:1', 'Jeremiah', 30, 1, '&nbsp;د مالِک خُدائ پېغام يرمياه ته ورکړے شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18556, 'Jeremiah 30:2', 'Jeremiah', 30, 2, '&nbsp;”دا هغه څۀ دى چې مالِک خُدائ د بنى اِسرائيلو خُدائ پاک يې فرمائى چې، ټولې هغه خبرې چې ما تا سره وکړې هغه په يو کِتاب کښې وليکه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18557, 'Jeremiah 30:3', 'Jeremiah', 30, 3, '&nbsp;مالِک خُدائ فرمائى چې، ګوره، نو هغه وخت راروان دے چې زۀ به خپل خلق اِسرائيل او يهوداه د جلاوطنۍ نه بحال کړم او هغه مُلک او ځائ ته به يې واپس راولم کوم چې ما د هغوئ پلار نيکۀ له په ميراث کښې ورکړے وو او دا به بيا د هغوئ ملکيت وى، دا مالِک خُدائ فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18558, 'Jeremiah 30:4', 'Jeremiah', 30, 4, '&nbsp;دا هغه خبرې دى چې مالِک خُدائ د اِسرائيل او يهوداه د خلقو په حقله فرمائيلى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18559, 'Jeremiah 30:5', 'Jeremiah', 30, 5, '&nbsp;”مالِک خُدائ فرمائى چې، زۀ د يرې ژړا اورم، هلته دهشت دے او امن نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18560, 'Jeremiah 30:6', 'Jeremiah', 30, 6, '&nbsp;نو زۀ به ستاسو نه دا يو تپوس وکړم چې ولې سړى بچى راوړى څۀ؟ نو دا ولې زۀ چې هر يو تکړه سړى ته ګورم نو لکه د يوې بيمارې ښځې په شان چې د ماشوم د پېدا کېدو وخت يې رانزدې شوے وى هغسې يې لاسونه په خپله ګېډه باندې اېښى وى او هر يو لکه د مړى په شان تک زېړ شوى وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18561, 'Jeremiah 30:7', 'Jeremiah', 30, 7, '&nbsp;افسوس چې هغه ورځ به څومره سخته وى. د هغې ورځې په شان به بله کومه ورځ هم نۀ وى. دا به د يعقوب دپاره سخته ورځ وى، خو په آخر کښې به هغه ترې بچ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18562, 'Jeremiah 30:8', 'Jeremiah', 30, 8, '&nbsp;مالِک خُدائ ربُ الافواج فرمائى چې، په هغه ورځ به د هغوئ د غاړې نه هغه جغ مات کړم او د زنځيرونو نه به يې خلاص کړم او هغوئ به نور د پردو خلقو غلامان نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18563, 'Jeremiah 30:9', 'Jeremiah', 30, 9, '&nbsp;خو هغوئ به د خپل مالِک خُدائ او د داؤد د نسل نه د هغه بادشاه خِدمت وکړى، څوک چې به زۀ په هغوئ باندې مقرروم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18564, 'Jeremiah 30:10', 'Jeremiah', 30, 10, '&nbsp;بلکې مالِک خُدائ فرمائى چې، اے زما خِدمت کوونکيه يعقوبه، مۀ يرېږه. او اے اِسرائيله تۀ مۀ پرېشانه کېږه. زۀ به په يقين سره تا او ستا اولاد په هغه لرې مُلک کښې د جلاوطنۍ نه آزاد کړم. او تۀ به راواپس شې او خير خيريت سره به ژوند کوې. او څوک به تا نۀ شى يرولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18565, 'Jeremiah 30:11', 'Jeremiah', 30, 11, '&nbsp;نو مالِک خُدائ فرمائى چې، زۀ ستا مل يم او زۀ به تا بچ کړم. او زۀ به هغه ټول قومونه مکمل تباه کړم چرته چې ما تاسو خوارۀ وارۀ کړى وئ، خو زۀ به تاسو په مکمل توګه نۀ تباه کوم. زۀ به تاسو په اِنصاف سره تنبيه کړم، او زۀ به تاسو هم داسې بې‌سزا نۀ پرېږدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18566, 'Jeremiah 30:12', 'Jeremiah', 30, 12, '&nbsp;مالِک خُدائ داسې فرمائى چې، ستاسو زخمونه خطرناک دى، او ستاسو زخمونه لاعلاجه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18567, 'Jeremiah 30:13', 'Jeremiah', 30, 13, '&nbsp;داسې څوک نشته چې ستا خيال وساتى، ستا د زخمونو دپاره دارو نشته، ستا دپاره علاج نشته دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18568, 'Jeremiah 30:14', 'Jeremiah', 30, 14, '&nbsp;ستا ټولو ملګرو تۀ هېر کړے يې، هغوئ ستا پرواه نۀ کوى. ما په تا باندې داسې حمله وکړه لکه څنګه چې په دشمن کوم، او د يو ظالم په شان مې سزا درکړه، ځکه چې ستا شرارتونه ډېر غټ دى، او ستا ګناهونه ډېر زيات دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18569, 'Jeremiah 30:15', 'Jeremiah', 30, 15, '&nbsp;نو بيا ولې تاسو په خپلو زخمونو او درد ژړا فرياد کوئ، او تاسو وايئ چې د دې خو هيڅ علاج نشته؟ خو دا ما ستاسو د لويو شرارتونو او ډېرو ګناهونو په وجه درسره وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18570, 'Jeremiah 30:16', 'Jeremiah', 30, 16, '&nbsp;خو هر هغه څوک چې تاسو روغ تېروى هغوئ به روغ تېر کړے شى، او ستاسو ټول دشمنان به جلاوطن کړے شى. هر هغه څوک چې تاسو لوټ کوى هغوئ به لوټ کړے شى، او څوک چې په تاسو باندې حمله کوى په هغوئ باندې به حمله وکړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18571, 'Jeremiah 30:17', 'Jeremiah', 30, 17, '&nbsp;مالِک خُدائ فرمائى چې، زۀ به ستاسو صحت دوباره ښۀ کړم، او ستاسو زخمونو ته به شفا ورکړم. زۀ به دا کار وکړم ځکه چې ما اورېدلى دى چې خلق تا ته ”جلاوطن شوے“ وائى، ”صيون د چا چې څوک هم خيال نۀ ساتى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18572, 'Jeremiah 30:18', 'Jeremiah', 30, 18, '&nbsp;مالِک خُدائ فرمائى چې، زۀ به د يعقوب اولاد د غلامۍ نه واپس راولم او په هغوئ به رحم وکړم، د يروشلم تباه شوے ښار به هم هغه ځائ کښې دوباره آباد کړم، او زوړ محل به يې په خپل اصلى ځائ کښې ودروم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18573, 'Jeremiah 30:19', 'Jeremiah', 30, 19, '&nbsp;نو په هغه وخت کښې به د هغه خلقو نه د شُکر ګزارۍ حمدونه او د خوشحالۍ آوازونه واورېدلے شى. زۀ به د هغوئ شمېر زيات کړم، او هغوئ به کمولے نۀ شى. زۀ به خلق مجبور کړم چې د هغوئ عزت وکړى، او هغوئ به سپک نۀ شمېرلے کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18574, 'Jeremiah 30:20', 'Jeremiah', 30, 20, '&nbsp;د هغوئ ماشومان به لکه د پخوا په شان ژوند کوى، او د هغوئ جماعت به زما په مخکښې قائم شى، او زۀ به هغه ټولو خلقو له سزا ورکړم څوک چې په دوئ باندې ظلم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18575, 'Jeremiah 30:21', 'Jeremiah', 30, 21, '&nbsp;د هغوئ مشر به د هغوئ د خپل قوم نه وى، او د هغوئ مشر به د هغوئ د خپلو خلقو نه وى. زۀ به هغه خپل ځان ته نزدې کړم او هغه به ما له راشى، ځکه چې څوک دا جرأت کولے شى چې نابللے راشى؟ دا د مالِک خُدائ فرمان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18576, 'Jeremiah 30:22', 'Jeremiah', 30, 22, '&nbsp;نو هغه وخت به تاسو زما خلق يئ او زۀ به ستاسو خُدائ پاک يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18577, 'Jeremiah 30:23', 'Jeremiah', 30, 23, '&nbsp;ګورئ د مالِک خُدائ غصه لکه د طوفان په شان رانازليږى، او د تېزو هواګانو په شان د بدعمله خلقو په سر په غضب سره لګيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18578, 'Jeremiah 30:24', 'Jeremiah', 30, 24, '&nbsp;او د مالِک خُدائ سخت قهر او غضب به تر هغې پورې وى او واپس به نۀ شى ترڅو چې د هغۀ مقصد پوره شوے نۀ وى. په راتلونکو ورځو کښې به تاسو په دې هر څۀ باندې پوهه شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18579, 'Jeremiah 31:1', 'Jeremiah', 31, 1, '&nbsp;مالِک خُدائ فرمائى چې، ”په هغه وخت کښې به زۀ د بنى اِسرائيلو د ټولو قبيلو خُدائ يم، او هغوئ به زما خلق وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18580, 'Jeremiah 31:2', 'Jeremiah', 31, 2, '&nbsp;مالِک خُدائ داسې فرمائى چې، ”د بنى اِسرائيلو کوم خلق چې د مرګ نه بچ پاتې شوى وُو ما په هغوئ په بيابان کښې فضل وکړو، کله چې هغوئ د آرام په تلاش کښې روان وُو ما د هغوئ ساتنه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18581, 'Jeremiah 31:3', 'Jeremiah', 31, 3, '&nbsp;ډېر پخوا مالِک خُدائ بنى اِسرائيلو ته راڅرګند شو، او ورته يې وفرمائيل چې، ما تاسو سره نۀ ختمېدونکې مينه کړې ده، ما تاسو په خپله مينه او رحم سره خپل ځان ته رانزدې کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18582, 'Jeremiah 31:4', 'Jeremiah', 31, 4, '&nbsp;زۀ به تا بيا آباد کړم، او تۀ به بيا آباد شې، اے پېغلې اِسرائيله. تۀ به بيا تمبل راواخلې او بهر به د ګډا دپاره په خوشحالۍ سره راووځې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18583, 'Jeremiah 31:5', 'Jeremiah', 31, 5, '&nbsp;تاسو به دوباره د سامريه په غونډو باندې د انګورو باغونه وکَرئ، او څوک چې دا باغونه کَرى هغوئ به يې په مېوه خوشحاله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18584, 'Jeremiah 31:6', 'Jeremiah', 31, 6, '&nbsp;نو هغه ورځ راروانه ده چې د اِفرائيم د غونډو نه به چوکيداران آوازونه وکړى او وائى به چې، راځئ چې صيون ته د عبادت دپاره او مالِک خُدائ خپل خُدائ پاک ته لاړ شو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18585, 'Jeremiah 31:7', 'Jeremiah', 31, 7, '&nbsp;مالِک خُدائ فرمائى چې، ”د يعقوب دپاره د خوشحالۍ سندرې ووايئ او چغې ووهئ چې بنى اِسرائيل د ټولو نه لوئ قوم دے. مالِک خُدائ ته د حمد و ثناء چغې ووهئ او ووايئ چې، اے مالِکه خُدايه، په بنى اِسرائيلو کښې پاتې شوے خپل قوم دې بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18586, 'Jeremiah 31:8', 'Jeremiah', 31, 8, '&nbsp;نو زۀ به هغوئ د شمالى مُلک نه واپس راولم او د زمکې د لرو ځايونو نه به يې راغونډ کړم. تر دې چې ړاندۀ، ګوډيان، اُميدوارې ښځې او د ماشوم د پېدا کېدو په حالت کښې ښځې، نو هغوئ ټول به د لوئ قبيلې په شکل کښې دلته بيا راواپس شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18587, 'Jeremiah 31:9', 'Jeremiah', 31, 9, '&nbsp;کله چې هغوئ واپس راشى نو د پښېمانۍ نه به اوښکې د هغوئ په مخ روانې وى او زۀ به هغوئ په ډېره مينه خپلو کورونو ته واپس بوځم، نو زۀ به هغوئ د روانو اوبو په خوا کښې او په هواره لاره بوځم هسې نه چې چرته تيندک وخورى، ځکه چې زۀ د بنى اِسرائيلو پلار يم، او اِفرائيم زما مشر زوئ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18588, 'Jeremiah 31:10', 'Jeremiah', 31, 10, '&nbsp;مالِک خُدائ فرمائى، ”اے قومونو، د مالِک خُدائ کلام واورئ، او هغه لرې ساحلى وطنونو ته يې بيان کړئ. هغه چا چې بنى اِسرائيل خوارۀ کړى دى هم هغه به يې راغونډ کړى. لکه څنګه چې شپونکے د خپلې رمې ساتنه کوى هم داسې به هغه د هغوئ خيال ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18589, 'Jeremiah 31:11', 'Jeremiah', 31, 11, '&nbsp;مالِک خُدائ به د بنى اِسرائيلو فديه ورکړى او هغوئ به د هغه کسانو نه آزاد کړى چې د دوئ نه زورَور دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18590, 'Jeremiah 31:12', 'Jeremiah', 31, 12, '&nbsp;هغوئ به راشى او پاس د صيون په غرۀ به د خوشحالۍ چغې ووهى، او هغوئ به د مالِک خُدائ په برکتونو لکه غله دانه، مے، تېل، او د رمو په زياتولو خوشحاله شى. د هغوئ ژوند به لکه د سيرابه باغ په شان وى، او هغوئ به نور غمژن نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18591, 'Jeremiah 31:13', 'Jeremiah', 31, 13, '&nbsp;نو پېغلې به د خوشحالۍ نه ګډيږى، ځوانان او بوډاګان به هم خوشحالى کوى. زۀ به د هغوئ غم په خوشحالۍ باندې بدل کړم، او زۀ به هغوئ له تسلى ورکړم، او زۀ به د هغوئ خفګان په خوشحالۍ بدل کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18592, 'Jeremiah 31:14', 'Jeremiah', 31, 14, '&nbsp;زۀ به د هغوئ اِمامان په غوړو زېړو خوراکونو ماړۀ کړم، او زما خلق به زما په نعمتونو باندې ماړۀ پټ شى. مالِک خُدائ دا فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18593, 'Jeremiah 31:15', 'Jeremiah', 31, 15, '&nbsp;مالِک خُدائ فرمائى چې، ”په راما کښې د چغو آواز واورېدلے شو، د ماتم او لوئ ژړا آواز. راحيل په خپلو بچو باندې ژړا کوى، هيڅ قسم تسلى نۀ قبلوى ځکه چې د هغې ماشومان غېب کړے شوى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18594, 'Jeremiah 31:16', 'Jeremiah', 31, 16, '&nbsp;خو مالِک خُدائ فرمائى چې، ”ژړا او اوښکې توېدل بس کړئ، تاسو ته به د خپلو کارونو اجر مِلاو شى.“ مالِک خُدائ داسې فرمائى چې، ”ستاسو ماشومان به د دشمن د مُلک نه راواپس شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18595, 'Jeremiah 31:17', 'Jeremiah', 31, 17, '&nbsp;مالِک خُدائ داسې فرمائى چې، ”ستا د راتلونکى ژوند دپاره اُميد شته دے، ستاسو ماشومان به خپل مُلک ته بيا واپس راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18596, 'Jeremiah 31:18', 'Jeremiah', 31, 18, '&nbsp;د اِفرائيم ژړا او فرياد ما ته رارسېدلے دے، تا ما ته تربيت راکړو چې په لاره شم، لکه د ناجوته سخى په شان دې تربيت راکړو او زۀ اوس په لاره شوے يم. ما دې خپل حضور ته واپس راوله، نو زۀ به واپس راشم، ځکه چې تۀ زما مالِک خُدائ او خُدائ پاک يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18597, 'Jeremiah 31:19', 'Jeremiah', 31, 19, '&nbsp;ستا نه د اوړېدو نه پس مونږ توبه وکړه، د پوهېدو نه وروستو مونږ خپله سينه ووهله. مونږ چې کوم کم عقل کارونه په ځوانۍ کښې کړى وُو د هغې په وجه سپک او شرمنده شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18598, 'Jeremiah 31:20', 'Jeremiah', 31, 20, '&nbsp;مالِک خُدائ فرمائى چې، ”ولې اِسرائيل تر اوسه زما محبوب زوئ نۀ دے څۀ په چا کښې چې زۀ خوشحالېږم؟ کۀ څۀ هم چې زۀ د دۀ خلاف بار بار خبرې کوم، نو بيا هم هغه يادوم. نو په دې وجه زما زړۀ ورپسې زهيريږى، زما په زړۀ کښې د دۀ دپاره ډېر رحم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18599, 'Jeremiah 31:21', 'Jeremiah', 31, 21, '&nbsp;اے زما قومه، تاسو د تلو په وخت په خپله لار داسې نښې ودروئ چې د هغې نه په واپسۍ کښې خلقو ته د صحيح لارې پته ولګى. اے پېغلې اِسرائيله راوګرځه، خپلو ښارونو ته راوګرځه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18600, 'Jeremiah 31:22', 'Jeremiah', 31, 22, '&nbsp;اے زما بې‌وفا لورې، تۀ به ترڅو پورې سرګردانه ګرځې؟ مالِک خُدائ به يو نوے کار وکړى او هغه دا دے چې بنى اِسرائيل به خپل مالِک خُدائ ته غاړه ورکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');